local Library = loadstring(game:HttpGet("https://raw.githubusercontent.com/NIcoGabrielRealYtr/Avilon-Library/refs/heads/main/Source"))()

local Window = Library:Window({
    Name = "Title",
    SubName = "SubTitle",
    Logo = "rbxassetid://114856413138528"  -- Your logo asset ID
})

local MainPage = Window:Page({
    Name = "Page",
    Icon = "rbxassetid://102973834692853"
})

-- Create SUBPAGE (only 1 subpage)
local SettingsSubPage = MainPage:SubPage({
    Name = "SubPage",
    Description = "All settings in one place",
    Icon = "rbxassetid://102973834692853"
})

-- ==================== LEFT SECTION (Side = 1) ====================
local LeftSection = SettingsSubPage:Section({
    Name = "Title",
    Description = "Description",
    Side = 1
})

-- 1. TOGGLE
local AimbotToggle = LeftSection:Toggle({
    Name = "Toggle",
    Flag = "AimbotEnabled",
    Default = false
})

local InfoLabel = LeftSection:Label({
    Name = "Label Title"
})

InfoLabel:Keybind({
    Name = "Title",
    Flag = "AimbotKey",
    Default = Enum.KeyCode.RightAlt,
    Mode = "Hold",  -- Toggle, Hold, or Always
    Callback = function(state)
        print("Aimbot key state:", state)
    end
})

LeftSection:Slider({
    Name = "ESP Transparency",
    Flag = "ESPTransparency",
    Default = 0.5,
    Min = 0,
    Max = 1,
    Decimals = 0.01,
    Suffix = "",
    Callback = function(Value)
        StatusLabel:SetText("Status: Transparency " .. tostring(Value))
    end
})

LeftSection:Dropdown({
    Name = "Target Priority",
    Flag = "TargetPriority",
    Default = "Closest",
    Items = {"Closest", "Lowest HP", "Highest HP", "Random"}
})

LeftSection:Textbox({
    Name = "Username",
    Flag = "BoxName",
    Default = "Player",
    Placeholder = "Enter name...",
    Finished = true
})

local RightSection = SettingsSubPage:Section({
    Name = "Title",
    Description = "Description",
    Side = 2
})

RightSection:Colorpicker({
    Name = "ESP Color",
    Flag = "ESPColor",
    Default = Color3.fromRGB(255, 0, 0),
    Alpha = 1
})

RightSection:Button({
    Name = "Teleport to Mouse",
    Callback = function()
    end
})

local StatusLabel = RightSection:Label({Name = "Status: Ready"})
